-- Room v5 -> v6, testes Labs isolados do histórico de sessões.
CREATE TABLE IF NOT EXISTS `lab_tests` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sky` TEXT NOT NULL, `skyChanges` TEXT NOT NULL, `panelWatts` INTEGER, `targetMs` INTEGER, `startedAt` INTEGER NOT NULL, `deadlineAt` INTEGER, `endedAt` INTEGER, `status` TEXT NOT NULL, `initialPercent` INTEGER, `finalPercent` INTEGER, `chargingMs` INTEGER NOT NULL, `notChargingMs` INTEGER NOT NULL, `weightedMaMs` REAL NOT NULL, `validCurrentMs` INTEGER NOT NULL, `lastReadingAt` INTEGER, `lastElapsedMs` INTEGER, `lastMode` TEXT, `lastCurrentMa` REAL, `lastCurrentSource` TEXT);
